      (ctx.made || []).map(iid => g.cards[iid]).filter(c => c && c.token).forEach(c => { c.pump = { pow: 0, tou: 0, ...c.pump, kw: [...new Set([...((c.pump && c.pump.kw) || []), 'haste'])] }; });
