  const plainLine = l => l.replace(/\([^)]*\)/g, '').trim().replace(/^(?!(?:[IVX]+(?:, [IVX]+)*|Max speed|Boast) —)[A-Z][A-Za-z'’ -]{1,40}? — (?=[A-Z{+−-])/, '')
