  const choosesCardType = (inst, defOf) => oracleLines(inst, defOf).some(l => /^as (?:this|.+?) enters, choose a card type\.?$/i.test(l));
  const cardTypeModes = () => CARD_TYPE_CHOICES.map(t => `The chosen card type is ${t}`);

