      const mine = Object.assign({ other: isOpps(game, s) ? game : game.bot ? game.bot.s : null, defOf }, ctx, { dealt: n });
      if (isOpps(game, s)) runFor(game, s, inst, m[2], `dealt ${n} damage`, { dealt: n }, defOf);
