          for (const a of list.filter(a => a.zone === 'battlefield' && other && stats(a, factsOf(a, defOf)).kw.has(m[1].toLowerCase()))) applyTarget(game, other, a, { action: 'damage', n, what: 'creature' }, w.name, defOf, t);
