        const d = h && destroyTheirs(h.effect);
        if (h && !d) runFor(game, s, inst, h.effect, 'combat damage to you', null, defOf, h.times);
        if (!d) continue;
        const pick = destroyable(game, d).sort((a, b) => ((defOf(b.id) || {}).cmc || 0) - ((defOf(a.id) || {}).cmc || 0))[0];
