  const hasType = (inst, w) => typeWords(inst).includes(w) || (isChangeling(inst) && /\bcreature\b/i.test(front(inst.typeLine)) && !CARD_TYPES.includes(w));
  // "non-Human creatures" (Return of the Wildspeaker): a word starting with non- rules a type out.
  // "Wolves and Werewolves", "Wolf or Werewolf" (Nightpack Ambusher, Hollowhenge Overlord): either one.
  const isA = (inst, phrase) => (/\s(?:and\/or|and|or)\s/i.test(phrase) ? phrase.split(/\s+(?:and\/or|and|or)\s+/i).some(p => isA1(inst, p)) : isA1(inst, phrase));
  const isA1 = (inst, phrase) => phrase.toLowerCase().split(/\s+/).filter(Boolean).map(singular).every(w => {
    if (w === 'multicolored' || w === 'monocolored') return colorCount(inst) > 1 === (w === 'multicolored') && colorCount(inst) > 0; // Rienne
    // Bad Moon's "Black creatures", Forsaken Monument's "Colorless creatures".
    if (PRO_COLORS[w]) return inst.allColors || (inst.tokenColors || inst.cardColors || (inst.bot && inst.bot.colors) || []).includes(PRO_COLORS[w]);
    if (w === 'colorless') return colorCount(inst) === 0;
    const not = /^non-?(.+)$/.exec(w);
    return not ? !hasType(inst, not[1]) : hasType(inst, w);
  });
  // How many colors a card is, from what's kept on it (game.js's cardColors, a token's colors, Opp's facts).
  const colorCount = inst => (inst.allColors ? 5 : (inst.tokenColors || inst.cardColors || (inst.bot && inst.bot.colors) || []).length);
  const permanents = s => s.zones.battlefield.map(iid => s.cards[iid]).filter(c => c && !c.faceDown && !c.phasedOut);

  // What other permanents give, all the time: keywords ("Goblins you control have haste", "Other
  // Rats you control have menace") and +X/+X ("Other Elves you control get +1/+1 and have
  // trample", "Pride Sovereign gets +1/+1 for each other Cat you control"). Stored on each
  // creature as granted and anthem (stats adds them); run after anything that changes a battlefield.
  // "Creatures your opponents control get -2/-2" (Elesh Norn) reaches the other table. Then a
  // creature left with 0 or less toughness goes to the graveyard, which can change the lords again.
  // Basalt Monolith; Treasure Nabber: "Whenever an opponent taps an artifact for mana, gain control of that artifact until the end of your next turn."
  const NO_UNTAP = /^this (?:artifact|creature|permanent) doesn't untap during your untap step\.?$/i;
  const LIER = /^each instant and sorcery card in your graveyard has flashback\. the flashback cost is equal to that card's mana cost\.?$/i;
  // Voracious Bibliophile: "Whenever you cast a spell with one or more targets, draw that many cards." (spellCast; the targets its text names)
  const BIBLIOPHILE = /^whenever you cast a spell with one or more targets, draw that many cards\.?$/i;
  const NABBER = /^whenever an opponent taps an artifact for mana, gain control of that artifact until the end of your next turn\.?$/i;
  // G.hooks.manaTapped (app.js, autoplay.js): table s tapped inst for mana; an artifact is queued for the other side's Treasure Nabber.
  function manaTapped(s, inst) {
    if (inst && !G.isLand(inst) && /\bartifact\b/i.test(front(inst.typeLine || ''))) s.nabbed = [...(s.nabbed || []), inst.iid];
  }
  // Notion Thief (G.hooks.drawInstead): table s would draw a card (first: the first one of its draw step, which it keeps). True when the
  // other side's Notion Thief takes the draw instead.
  const NOTION = /^if an opponent would draw a card except the first one they draw in each of their draw steps, instead that player skips that draw and you draw a card\.?$/i;
  let stealingDraw = false;
  function drawInstead(game, s, first, defOf) {
    // Dredge (Life from the Loam): a card you marked in your graveyard (app.js's graveyard menu) comes back instead of this draw.
    const dredge = s.zones.graveyard.map(iid => s.cards[iid]).find(c => c.dredgeNext);
    if (dredge) {
      const n = Number((oracleLines(dredge, defOf).map(l => /^dredge (\d+)$/i.exec(l)).find(Boolean) || [])[1]) || 0;
      delete dredge.dredgeNext;
      if (s.zones.library.length >= n) { G.mill(s, n); G.move(s, dredge.iid, 'hand'); G.log(s, `Dredged ${dredge.name} (milled ${n}) instead of drawing.`); return true; }
    }
    if (first || stealingDraw || !game.bot) return false;
    const other = s === game ? game.bot.s : game;
    const thief = permanents(other).find(w => oracleLines(w, defOf).some(l => NOTION.test(l)));
    if (!thief) return false;
    stealingDraw = true;
    try { G.drawCards(other, 1, isOpps(game, other)); } finally { stealingDraw = false; }
    G.log(s, `${thief.name}: that draw was skipped, and its controller drew instead.`);
    return true;
  }
  // Dauthi Voidwalker (G.hooks.graveInstead): a card of table s headed to its graveyard is exiled with a void counter when the other side has one.
  const DAUTHI = /^if a card would be put into an opponent's graveyard from anywhere, instead exile it with a void counter on it\.?$/i;
  function graveInstead(game, s, inst, defOf) {
    if (!game.bot || !inst) return false;
    const other = s === game ? game.bot.s : game;
    return permanents(other).some(w => oracleLines(w, defOf).some(l => DAUTHI.test(l)));
  }
  // At the end of table t's turn: what its Treasure Nabber took goes back (c.lentUntil: the turn it's kept through).
  function returnLent(game, t, defOf) {
    const owner = t === game ? game.bot && game.bot.s : game;
    for (const c of permanents(t).filter(p => p.lentUntil && t.turn >= p.lentUntil)) {
      delete c.lentUntil;
      if (owner) { const back = gainControl(t, c.iid, owner, defOf); if (back) G.log(t, `${back.name} went back to its owner (Treasure Nabber).`); }
    }
  }
  function refreshGrants(game, defOf) {
    lastDefOf = defOf || lastDefOf; // for the few places that don't get one (oppSacrifices' watchers)
    const tables = [game, game.bot && game.bot.s].filter(Boolean);
    lastTables = tables;
    thawCopies(game);
    if (game.bot) syncAuras(game); // automatic games too (app.js also calls it)
    // Oubliette: the creature it holds phases back in, tapped, once it's gone.
    for (const t of tables) {
      for (const c of Object.values(t.cards).filter(x => x.heldBy && x.zone === 'battlefield')) {
        const holder = (c.heldBy.who === 'you' ? game : game.bot && game.bot.s) || null;
        const h = holder && holder.cards[c.heldBy.iid];
        if (h && h.zone === 'battlefield') continue;
        delete c.heldBy;
        delete c.phasedOut;
        c.tapped = true;
        G.log(t, `${c.name} phased back in, tapped.`);
      }
    }
    // Animate Dead: "When this Aura leaves the battlefield, that creature's controller sacrifices it."
    for (const t of tables) {
      for (const c of permanents(t).filter(p => p.animatedBy)) {
        const a = t.cards[c.animatedBy];
        if (a && a.zone === 'battlefield' && a.attachedTo === c.iid) continue;
        delete c.animatedBy;
        G.move(t, c.iid, c.commander ? 'command' : 'graveyard');
        G.log(t, `${c.name} was sacrificed: the aura that returned it is gone.`);
      }
    }
    // Lier, Disciple of the Drowned: "Each instant and sorcery card in your graveyard has flashback. The flashback cost is equal to that card's mana cost."
    for (const t of tables) {
      const lier = permanents(t).some(c => oracleLines(c, defOf).some(l => LIER.test(l)));
      for (const iid of t.zones.graveyard) {
        const c = t.cards[iid];
        if (lier && /\b(instant|sorcery)\b/i.test(front(c.typeLine || ''))) c.lierFlashback = (c.bot && c.bot.cost) || (defOf(c.id) || {}).manaCost || '';
        else delete c.lierFlashback;
      }
    }
    // Basalt Monolith: "This artifact doesn't untap during your untap step." (game.js's nextTurn reads c.noUntap)
    for (const t of tables) {
      for (const c of permanents(t)) {
        if (oracleLines(c, defOf).some(l => NO_UNTAP.test(l))) c.noUntap = true;
        else delete c.noUntap;
      }
    }
    // Treasure Nabber (the other side's): artifacts tapped for mana change sides now that the paying is done (G.hooks.manaTapped queued them).
    for (const t of tables) {
      const q = t.nabbed || [];
      delete t.nabbed;
      const other = tables.find(x => x !== t);
      for (const iid of q) {
        const c = t.cards[iid];
        if (!c || c.zone !== 'battlefield' || !other || !permanents(other).some(w => oracleLines(w, defOf).some(l => NABBER.test(l)))) continue;
        const got = gainControl(t, iid, other, defOf);
        if (got) { got.lentUntil = other.turn + 1; G.log(other, `Treasure Nabber: took ${got.name} until the end of its controller's next turn.`); }
      }
    }
    // Mazemind Tome: "When there are four or more page counters on this artifact, exile it. If you do, you gain 4 life."
    for (const t of tables) {
      for (const c of permanents(t)) {
        const m = oracleLines(c, defOf).map(l => /^when there are (\w+) or more ([\w+/-]+) counters on (?:this \w+|it), exile it\. if you do, you gain (\w+) life\.?$/i.exec(l)).find(Boolean);
        if (!m || ((c.counters || {})[m[2].toLowerCase()] || 0) < toNumber(m[1])) continue;
        G.move(t, c.iid, 'exile');
        if (t === game) game.life += toNumber(m[3]);
        else game.oppLife += toNumber(m[3]);
        G.log(t, `${c.name} had ${m[1]} ${m[2]} counters, so it was exiled and ${toNumber(m[3])} life gained.`);
      }
    }
    // Start your engines! (Howlsquad Heavy): its controller's speed starts at 1, and goes up 1 (to 4) once each turn of theirs that an opponent
    // lost life (t.speedLife: that opponent's life when the turn began, upkeepSuspend). At 4, "Max speed — …" lines count (byLevel).
    for (const t of tables) {
      if (!t.speed && permanents(t).some(c => oracleLines(c, defOf).some(l => /^start your engines!?$/i.test(l)))) t.speed = 1;
      if (!t.speed) continue;
      const theirs = lifeOf(game, t === game ? 'opp' : 'you');
      if (t.speed < 4 && !t.offTurn && t.speedUpTurn !== t.turn && t.speedLife && t.speedLife.turn === t.turn && theirs < t.speedLife.life) {
        t.speed++;
        t.speedUpTurn = t.turn;
        G.log(t, `Speed ${t.speed}${t.speed === 4 ? ' (max speed)' : ''}.`);
      }
      permanents(t).forEach(c => { if (t.speed >= 4) c.maxSpeed = true; else delete c.maxSpeed; });
    }
    // Turbulent lands: "… unless your opponents control eight or more lands" (game.js's tapsOnEntry).
    tables.forEach(t => { const o = tables.find(x => x !== t); if (o) t.oppLandCount = permanents(o).filter(G.isLand).length; });
    // Archelos: other permanents enter tapped while it's tapped, untapped while it's untapped (every table).
    let state = null;
    for (const t of tables) for (const c of permanents(t)) if (oracleLines(c, defOf).some(l => /^as long as (.+?) is tapped, other permanents enter tapped\.?$/i.test(l))) state = { src: c.iid, tapped: !!c.tapped };
    // Blind Obedience, Authority of the Consuls, Thalia, Heretic Cathar: "Creatures and nonbasic lands your opponents control enter tapped."
    // (game.js's tapsOnEntry: t.tapKinds, from the other tables' cards)
    tables.forEach(t => {
      const kinds = tables.filter(o => o !== t).flatMap(o => permanents(o)).flatMap(c => oracleLines(c, defOf).map(l => OPPS_ENTER_TAPPED.exec(l)).filter(Boolean))
        .flatMap(m => m[1].toLowerCase().split(/,\s*(?:and\s+)?|\s+and\s+/).map(k => singular(k.trim())));
      if (kinds.length) t.tapKinds = [...new Set(kinds)];
      else delete t.tapKinds;
      // Narset, Parter of Veils: "Each opponent can't draw more than one card each turn." (game.js's drawCards)
      if (tables.some(o => o !== t && permanents(o).some(c => oracleLines(c, defOf).some(l => DRAW_CAP.test(l))))) t.drawCap = 1;
      else delete t.drawCap;
      // Soulless Jailer (anyone's): "Permanent cards in graveyards can't enter the battlefield." (game.js's move) "Players can't cast
      // noncreature spells from graveyards or exile." (castOptions, app.js's tryPlay)
      const jailer = re => tables.some(o => permanents(o).some(c => oracleLines(c, defOf).some(l => re.test(l))));
      if (jailer(GRAVE_LOCK)) t.graveLocked = true;
      else delete t.graveLocked;
      if (jailer(NO_GRAVE_CAST)) t.noGraveCast = true;
      else delete t.noGraveCast;
      // Aven Mindcensor: "If an opponent would search a library, that player searches the top four cards of that library instead." (searchable)
      if (tables.some(o => o !== t && permanents(o).some(c => oracleLines(c, defOf).some(l => SEARCH_TOP.test(l))))) t.searchTop = 4;
      else delete t.searchTop;
      // Archetype of Imagination: "Creatures your opponents control lose flying and can't have or gain flying." (stats)
      const lost = [...new Set(tables.filter(o => o !== t).flatMap(o => permanents(o)).flatMap(c => oracleLines(c, defOf).map(l => KW_LOST.exec(l)).filter(Boolean)).map(m => m[1].toLowerCase()))];
      permanents(t).forEach(c => { if (lost.length) c.lostKw = lost; else delete c.lostKw; });
      // Stormtide Leviathan (anyone's): "All lands are Islands in addition to their other types." (walksPast) "Creatures without flying or
      // islandwalk can't attack." (stats)
      const allLines = tables.flatMap(o => permanents(o)).flatMap(c => oracleLines(c, defOf));
      // Absolute Virtue: "You have protection from each of your opponents." (proFromOpps)
      if (permanents(t).some(c => oracleLines(c, defOf).some(l => PRO_FROM_OPPS.test(l)))) t.proFromOpps = true;
      else delete t.proFromOpps;
      if (allLines.some(l => ALL_ISLANDS.test(l))) t.allIslands = true;
      else delete t.allIslands;
      const needs = allLines.map(l => GROUNDED.exec(l)).find(Boolean);
      permanents(t).forEach(c => { if (needs) c.attackNeeds = [needs[1].toLowerCase(), needs[2].toLowerCase()]; else delete c.attackNeeds; });
    });
    // Archivist of Oghma: "Whenever an opponent searches their library, you gain 1 life and draw a card." (applySearch counts the searches)
    for (const t of tables.filter(x => x.searchesSeen)) {
      const n = t.searchesSeen;
      delete t.searchesSeen;
      for (const o of tables.filter(x => x !== t)) {
        for (const w of permanents(o)) {
          const m = oracleLines(w, defOf).map(l => SEARCH_WATCH.exec(l)).find(Boolean);
          if (m) runFor(game, o, w, m[1], 'an opponent searched their library', null, defOf, n);
        }
      }
    }
    // Omnath, Locus of the Void: "If you would lose unspent mana, that mana becomes colorless instead."
    tables.forEach(t => {
      if (state) t.enterState = state;
      else delete t.enterState;
      t.keepMana = permanents(t).some(c => oracleLines(c, defOf).some(l => /^if you would lose unspent mana, that mana becomes colorless instead\.?$/i.test(l)));
    });
    for (let i = 0; i < 30; i++) { // Massacre Girl can take many rounds
      grantsOnce(tables, defOf);
      if (!zeroToughness(tables, defOf)) return;
    }
  }

  // Puts each creature with 0 or less toughness into its owner's graveyard (its commander into the
  // command zone). Indestructible doesn't help. One whose toughness is "*" and that nothing here
  // works out is left alone. Returns true if any died.
  function zeroToughness(tables, defOf) {
    let any = false;
    for (const s of tables) {
      for (const c of creatures(s)) {
        if (c.copyPending) continue; // Wall of Stolen Identity before you pick what it copies
        const card = c.bot || defOf(c.id) || {};
        const printed = c.custom && c.custom.pt ? String(c.custom.pt).split('/')[1] : card.toughness;
        if (!/^-?\d+$/.test(String(printed == null ? '' : printed).trim()) && !c.cda) continue;
        if (stats(c, card).tou > 0) continue;
        G.log(s, `${c.name} has 0 or less toughness.`);
        G.move(s, c.iid, c.commander ? 'command' : 'graveyard');
        any = true;
      }
    }
    return any;
  }

  // A spell's discount on itself, from table s: "This spell costs {X} less to cast, where X is the
  // total toughness of creatures you control" (The Pride of Hull Clade) or "This spell costs {1}
  // less to cast for each Wall you control". Only generic mana comes off (autoPay).
  const GRAVE_TYPES_DISCOUNT = /^this spell costs \{(\d+)\} less to cast for each card type among cards in your graveyard\.?$/i;
  const SELF_DISCOUNT = /^this spell costs \{(x|\d+)\} less to cast(?:, where x is the total (power|toughness) of (.+?) you control| for each (.+?) you control)\.?$/i;
  // other: the other side's table (yours when s is Opp's; Opp's when s is yours, found by itself).
  const PROWLER = /^spells you cast cost \{(\d+)\} less to cast for each card type they share with cards exiled with this creature\.?$/i;
  const HOARD = /^this spell costs \{x\} less to cast, where x is the greatest number of (\w+) an opponent controls\.?$/i;
  function selfDiscount(s, inst, defOf, other = s.bot && s.bot.s) {
    let total = 0;
    // Zimone, Infinite Analyst: the first {X} spell each turn costs {1} less for each +1/+1 counter on Zimone.
    if (hasX(inst, defOf) && !(s.spellTurn === s.turn && (s.castThisTurn || []).some(c => hasX(c, defOf)))) {
      for (const z of permanents(s)) {
        const m = oracleLines(z, defOf).map(l => /^the first spell you cast with \{x\} in its mana cost each turn costs \{(\d+)\} less to cast for each ([\w+/-]+) counter on (.+?)\.?$/i.exec(l)).find(Boolean);
        if (m && isSelf(m[3], z)) total += Number(m[1]) * ((z.counters || {})[m[2].toLowerCase()] || 0);
      }
    }
    // Cemetery Prowler: "Spells you cast cost {1} less to cast for each card type they share with cards exiled with this creature."
    for (const z of permanents(s)) {
      const m = oracleLines(z, defOf).map(l => PROWLER.exec(l)).find(Boolean);
      if (!m) continue;
      const types = c => CARD_TYPE_NAMES.filter(k => new RegExp(`\\b${k}\\b`, 'i').test(front(c.typeLine || '')));
      const under = new Set([s, other].filter(t => t && t.zones).flatMap(t => t.zones.exile.map(iid => t.cards[iid]).filter(c => c && c.exiledWith === z.iid)).flatMap(types));
      total += Number(m[1]) * types(inst).filter(k => under.has(k)).length;
    }
    for (const line of oracleLines(inst, defOf)) {
      // Metalwork Colossus: "This spell costs {X} less to cast, where X is the total mana value of noncreature artifacts you control."
      if (/^this spell costs \{x\} less to cast, where x is the total mana value of noncreature artifacts you control\.?$/i.test(line)) total += permanents(s).filter(c => isA(c, 'artifact') && !G.isCreature(c)).reduce((n, c) => n + cmcOfInst(c, defOf), 0);
      // Avenge: "… if a player attacked you during their last turn"; Heroic Return: "… if a creature is attacking you"; Mortality Spear: "… if you gained life this turn".
      const m = /^this spell costs \{(\d+)\} less to cast if (a player attacked you during their last turn|a creature is attacking you|you gained life this turn)\.?$/i.exec(line);
      if (m && (/attacked/i.test(m[2]) ? !!(other && other.attackedYou) : /gained/i.test(m[2]) ? s.gainTurn === s.turn : !!s.attackersNow)) total += Number(m[1]);
      // Game Over: "This spell costs {2} less to cast if a player's life total is less than or equal to half their starting life total."
      const half = /^this spell costs \{(\d+)\} less to cast if a player's life total is less than or equal to half their starting life total\.?$/i.exec(line);
      if (half && [s, other].some(t => t && t.zones && t.life <= (t.commander ? 40 : 20) / 2)) total += Number(half[1]);
      // Seeds of Renewal: "Undaunted" ({1} less for each opponent). Bitter Downfall: "… if it targets a creature that was dealt damage
      // this turn" (when there's such a creature to target).
      if (/^undaunted$/i.test(line)) total += s.opponents || 1;
      // Draconic Lore: "This spell costs {2} less to cast if you control a Dragon."
      const ifc = /^this spell costs \{(\d+)\} less to cast if you control an? (\w+)\.?$/i.exec(line);
      if (ifc && permanents(s).some(c => isA(c, ifc[2]))) total += Number(ifc[1]);
      // Cavern-Hoard Dragon: "This spell costs {X} less to cast, where X is the greatest number of artifacts an opponent controls."
      const hoard = HOARD.exec(line);
      if (hoard && other && other.zones) total += permanents(other).filter(c => isA(c, singular(hoard[1]))).length;
      const dd = /^this spell costs \{(\d+)\} less to cast if it targets a creature that was dealt damage this turn\.?$/i.exec(line);
      if (dd && [s, other].some(t => t && t.zones && creatures(t).some(c => c.damageTaken > 0))) total += Number(dd[1]);
    }
    for (const line of oracleLines(inst, defOf)) {
      // Emrakul, the Promised End: "This spell costs {1} less to cast for each card type among cards in your graveyard."
      const gt = GRAVE_TYPES_DISCOUNT.exec(line);
      if (gt) total += Number(gt[1]) * new Set(s.zones.graveyard.flatMap(iid => CARD_TYPE_NAMES.filter(k => new RegExp(`\\b${k}\\b`, 'i').test(front(s.cards[iid].typeLine || ''))))).size;
      const m = SELF_DISCOUNT.exec(line);
      if (!m) continue;
      const mine = what => permanents(s).filter(c => isA(c, what));
      if (m[2] && /^x$/i.test(m[1])) {
        total += mine(m[3]).reduce((n, c) => { const st = stats(c, c.bot || defOf(c.id)); return n + Math.max(0, /power/i.test(m[2]) ? st.pow : st.tou); }, 0);
      } else if (m[4] && /^\d+$/.test(m[1])) total += Number(m[1]) * mine(m[4]).length;
    }
    for (const line of oracleLines(inst, defOf)) {
      let m;
      // Affinity for artifacts / for Islands (Broodstar, Thoughtcast, Spire Golem): {1} less for each one you control.
      if ((m = /^affinity for (\w+)$/i.exec(line))) total += permanents(s).filter(c => isA(c, singular(m[1]))).length;
      // Furygale Flocking: "This spell costs {1} less to cast for each instant and sorcery card in your graveyard."
      if ((m = /^this spell costs \{(\d+)\} less to cast for each (.+?) cards? in your graveyard\.?$/i.exec(line))) {
        const kinds = m[2].split(/\s+and\s+|\s+or\s+|,\s*/).filter(Boolean);
        total += Number(m[1]) * s.zones.graveyard.filter(iid => kinds.some(k => cardFits(s.cards[iid], k))).length;
      }
      // Delve (Treasure Cruise): {1} less for each card in your graveyard (spellCast exiles them).
      if (/^delve$/i.test(line)) total += s.zones.graveyard.filter(iid => iid !== inst.iid).length;
      // Blasphemous Act: "This spell costs {1} less to cast for each creature on the battlefield."
      if ((m = /^this spell costs \{(\d+)\} less to cast for each creature on the battlefield\.?$/i.exec(line))) {
        const tables = [s, other].filter(Boolean);
        total += Number(m[1]) * tables.reduce((n, t) => n + creatures(t).length, 0);
      }
    }
    // Herald of War: "Angel spells and Human spells you cast cost {1} less to cast for each +1/+1 counter on this creature."
    // Goreclaw: "Creature spells you cast with power 4 or greater cost {2} less to cast."
    for (const src of permanents(s)) {
      for (const line of oracleLines(src, defOf)) {
        let m = /^(\w+) spells and (\w+) spells you cast cost \{(\d+)\} less to cast for each ([\w+/-]+) counter on (?:this creature|it)\.?$/i.exec(line);
        if (m && (isA(inst, m[1]) || isA(inst, m[2]))) total += Number(m[3]) * ((src.counters || {})[m[4].toLowerCase()] || 0);
        m = /^creature spells you cast with power (\d+) or greater cost \{(\d+)\} less to cast\.?$/i.exec(line);
        if (m && G.isCreature(inst) && num(factsOf(inst, defOf).power) >= Number(m[1])) total += Number(m[2]);
      }
    }
    return total;
  }

  // "Each creature you control with defender assigns combat damage equal to its toughness rather
  // than its power and can attack as though it didn't have defender" (Arcades), "Each creature
  // assigns …" (Doran, every table's), "Creatures you control can attack as though they didn't have
  // defender" (High Alert), "Wall creatures can attack …" (Rolling Stones). Returns
  // { what, mine, self, kw, tough, attack } or null.
  const TOUGH_RULE = /^each (.+?)( you control)?(?: with ([a-z ]+?))? assigns combat damage equal to its toughness rather than its power( and can attack as though it didn['’]?t have defender)?\.?$/i;
  const DEFENDER_RULE = /^(?:each )?(.+?)( you control)?(?: with ([a-z ]+?))? can attack as though (?:it|they) didn['’]?t have defender\.?$/i;
  function combatRuleOf(line, src) {
    // Baldin, Century Herdmaster: "During your turn, each creature assigns combat damage …" (only on its controller's turn: grantsOnce)
    const during = /^during your turn, /i.test(line);
    let m = TOUGH_RULE.exec(line.replace(/^during your turn, /i, ''));
    if (m) return { what: m[1], mine: !!m[2], self: false, kw: (m[3] || '').toLowerCase(), tough: true, attack: !!m[4], ...(during ? { yourTurn: true } : {}) };
    m = DEFENDER_RULE.exec(line);
    if (!m || m[1].includes(':')) return null;
    const self = isSelf(m[1], src);
    return { what: m[1], mine: !!m[2] || self, self, kw: (m[3] || '').toLowerCase(), tough: false, attack: true };
  }

  // What your Ring-bearer has once the Ring has tempted you twice, three times and four or more times
  // (the first time: legendary and "can't be blocked by creatures with greater power", grantsOnce).
  // The third is done by becameBlocked and combatOver.
  const RING_LINES = ['Whenever this creature attacks, draw a card, then discard a card.',
    "Whenever this creature becomes blocked by a creature, that creature's controller sacrifices it at end of combat.",
    'Whenever this creature deals combat damage to a player, each opponent loses 3 life.'];
  function grantsOnce(tables, defOf) {
    const kwList = text => text.toLowerCase().split(/,\s*(?:and\s+)?|\s+and\s+/).map(k => k.trim()).filter(Boolean);
    // "Creatures your opponents control get -2/-2": from each table, for the other ones.
    const hostile = [];
    const fighting = []; // combatRuleOf's rules, from each table
    const everyone = []; // Marrow-Gnawer: "All Rats have fear." (every table)
    allWither = false;
    noPrevent = false;
    let coats = 0; // Coat of Arms
    for (const s of tables) {
      for (const src of permanents(s)) {
        for (const line of oracleLines(src, defOf)) {
          const m = /^(.+?) your opponents control get ([+-]\d+)\/([+-]\d+)\.?$/i.exec(line);
          if (m && !m[1].includes(':')) hostile.push({ from: s, what: m[1], pow: Number(m[2]), tou: Number(m[3]) });
          // Toxrill, the Corrosive: "Creatures you don't control get -1/-1 for each slime counter on them."
          const tx = /^creatures you don't control get ([+-]\d+)\/([+-]\d+) for each ([\w+/-]+) counter on them\.?$/i.exec(line);
          if (tx) hostile.push({ from: s, what: 'creature', pow: Number(tx[1]), tou: Number(tx[2]), perCounter: tx[3].toLowerCase() });
          // Kulrath Knight: "Creatures your opponents control with counters on them can't attack or block."
          if (/^creatures your opponents control with counters on them can't attack or block\.?$/i.test(line)) hostile.push({ from: s, what: 'creature', pow: 0, tou: 0, kws: ["can't attack", "can't block"], test: c => Object.values(c.counters || {}).some(v => v > 0) });
          // Everlasting Torment: "All damage is dealt as though its source had wither." (combat: the keyword; other damage: creatureDamaged)
          if (/^all damage is dealt as though its source had wither\.?$/i.test(line)) { everyone.push({ src: null, other: false, what: 'creature', kws: ['wither'], pow: 0, tou: 0 }); allWither = true; }
          if (/^damage can't be prevented\.?$/i.test(line)) noPrevent = true; // Everlasting Torment (preventsDamage)
          const a = /^all (.+?) (?:have (.+?)|get ([+-]\d+)\/([+-]\d+))\.?$/i.exec(line);
          if (a && !a[1].includes(':')) everyone.push({ src: null, other: false, what: a[1], kws: grantKws(a[2] || ''), pow: Number(a[3] || 0), tou: Number(a[4] || 0) });
          // Lord of the Undead: "Other Zombie creatures get +1/+1."; Bad Moon: "Black creatures get +1/+1." (every table)
          const o = /^(other )?(\w+) creatures get ([+-]\d+)\/([+-]\d+)\.?$/i.exec(line);
          if (o && !/^(?:all|each)$/i.test(o[2])) everyone.push({ src, other: !!o[1], what: `${o[2]} creature`, kws: [], pow: Number(o[3]), tou: Number(o[4]) });
          if (/^each creature gets \+1\/\+1 for each other creature on the battlefield that shares at least one creature type with it\.?$/i.test(line)) coats++;
          const f = combatRuleOf(line, src);
          if (f) fighting.push({ from: s, src, ...f });
        }
      }
    }
    for (const s of tables) {
      const lords = hostile.filter(h => h.from !== s).map(h => ({ src: null, other: false, what: h.what, kws: h.kws || [], pow: h.pow, tou: h.tou, test: h.test, perCounter: h.perCounter })).concat(everyone);
      const each = []; // "This gets +1/+1 for each other Cat you control"
      const threshold = []; // Dirty Wererat: "As long as there are seven or more cards in your graveyard, this creature gets +2/+2 and can't block."
      const quoted = []; // 'Commander creatures you own have "Whenever this creature attacks …"'
      const types = []; // Roshan: "Other creatures you control are Assassins in addition to their other types."
      const sneaky = []; // Tetsuko Umezawa: "Creatures you control with power or toughness 1 or less can't be blocked."
      const byColors = []; // Knight of New Alara: "+1/+1 for each of its colors"
      const extras = []; // staticExtra's: (c, st) → { pow, tou, kws, types, basePT } for creature c
      s.extraC = 0; // Forsaken Monument
      // Hardened Scales, Ozolith, Kami of Whispered Hopes, Benevolent Hydra: "that many plus one +1/+1 counters" (game.js's counter)
      s.counterPlus = permanents(s).flatMap(c => oracleLines(c, defOf).map(l => /^if one or more \+1\/\+1 counters would be put on (another creature|an? [a-z ]+?) you control, that many plus one \+1\/\+1 counters are put on (?:it|that permanent) instead\.?$/i.exec(l)).filter(Boolean)
        .map(m => ({ what: m[1].toLowerCase().replace(/^(?:an?|another) /, ''), not: /^another/i.test(m[1]) ? c.iid : null })));
      // Donatello, the Brains: "If one or more tokens would be created under your control, those tokens plus a Mutagen token are created
      // instead." (game.js's tokenCount makes them)
      s.plusMutagen = permanents(s).filter(c => oracleLines(c, defOf).some(l => PLUS_MUTAGEN.test(l))).length ? ARTIFACT_TOKENS.mutagen : null;
      // Mirari's Wake, Vorinclex: "Whenever you tap a land for mana, add one mana of any type that land produced." (game.js's sourceOf)
      s.landDouble = permanents(s).filter(c => oracleLines(c, defOf).some(l => /^whenever you tap a land for mana, add one mana of any type that land produced\.?$/i.test(l))).length;
      // Vorinclex: "Whenever an opponent taps a land for mana, that land doesn't untap during its controller's next untap step." (on the other table; game.js's autoPay)
      s.landsFrozen = tables.filter(t => t !== s).some(o => permanents(o).some(c => oracleLines(c, defOf).some(l => /^whenever an opponent taps a land for mana, that land doesn't untap during its controller's next untap step\.?$/i.test(l))));
      // Goldspan Dragon: 'Treasures you control have "{T}, Sacrifice this artifact: Add two mana of any one color."' (game.js's sourceOf)
      s.treasureMana = permanents(s).some(c => oracleLines(c, defOf).some(l => /^treasures you control have "\{t\}, sacrifice this artifact: add two mana of any one colou?r\.?"\.?$/i.test(l))) ? 2 : 0;
      s.keepRed = false; // Leyline Tyrant
      s.counterMana = null; // Rishkar
      const other = tables.find(t => t !== s);
      s.playerPro = null; // Serra's Emissary: "You … have protection from the chosen card type."
      s.noMinusCounters = false; // Darksteel Angel
      s.cantLose = false;
      for (const src of [...permanents(s), ...emblemsOf(s)]) {
        for (let line of oracleLines(src, defOf)) {
          // Gratuitous Violence: creatures you control deal double damage (stats' kw, see hitOf).
          if (/^if a creature you control would deal damage to a permanent or player, it deals double that damage instead\.?$/i.test(line)) { lords.push({ src, other: false, what: 'creature', kws: [DOUBLE_DMG], pow: 0, tou: 0 }); continue; }
          if (PLUS_ONE.test(line)) { lords.push({ src, other: true, what: 'creature', kws: [PLUS_DMG], pow: 0, tou: 0 }); continue; } // Thor (other sources: damagePlayer, applyTarget)
          // Serra's Emissary: "You and creatures you control have protection from the chosen card type."
          if (/^you and creatures you control have protection from the chosen card type\.?$/i.test(line)) {
            if (src.chosenCardType) { s.playerPro = src.chosenCardType; lords.push({ src, other: false, what: 'creature', kws: [`protection from ${src.chosenCardType}`], pow: 0, tou: 0 }); }
            continue;
          }
          // Skrelv's Hive (corrupted): "As long as an opponent has three or more poison counters, creatures you control with toxic have lifelink."
          let c = /^as long as an opponent has (\w+) or more poison counters, (.+?) you control with (\w+) have (.+?)\.?$/i.exec(line);
          if (c) { if (other && (other.poison || 0) >= toNumber(c[1])) lords.push({ src, other: false, what: c[2], withKw: c[3].toLowerCase(), kws: grantKws(c[4]), pow: 0, tou: 0 }); continue; }
          // Knight of New Alara.
          c = /^each other (multicolored )?creature you control gets \+1\/\+1 for each of its colors\.?$/i.exec(line);
          if (c) { byColors.push({ src, multi: !!c[1] }); continue; }
          // Omnath: "+1/+1 for each unspent mana you have"; Faeburrow Elder: "for each color among permanents you control".
          c = /^(.+?) gets \+1\/\+1 for each (unspent mana you have|color among permanents you control)\.?$/i.exec(line);
          if (c && isSelf(c[1], src)) {
            const n = /mana/i.test(c[2]) ? Object.values(s.mana || {}).reduce((k, v) => k + (v || 0), 0) : new Set(permanents(s).flatMap(p => colorsOfInst(p, defOf))).size;
            each.push({ src, pow: 1, tou: 1, fixed: n });
            continue;
          }
          // The FDC precons' always-on lines (see staticExtra).
          const fx = staticExtra(s, other, src, line, defOf, tables);
          if (fx) { extras.push(fx); continue; }
          // Darksteel Angel.
          if (/^creatures you control can't have -1\/-1 counters put on them\.?$/i.test(line)) { s.noMinusCounters = true; continue; }
          if (/^you can't lose the game and your opponents can't win the game\.?$/i.test(line)) { s.cantLose = true; continue; }
          let q = /^(other )?(.+?) you (?:control|own) have "(.+)"\.?$/i.exec(line);
          // Hexing Squelcher: 'Other creatures you control have "Ward—Pay 2 life."' is the keyword ward (Opp doesn't target them).
          if (q && !q[2].includes(':') && /^ward—pay \d+ life\.?$/i.test(q[3])) { lords.push({ src, other: !!q[1], what: q[2], withKw: '', kws: ['ward'], pow: 0, tou: 0, color: null }); continue; }
          if (q && !q[2].includes(':')) { quoted.push({ src, other: !!q[1], what: q[2], line: q[3] }); continue; }
          q = /^other creatures you control are (\w+?)s? in addition to their other types\.(.*)$/i.exec(line);
          if (q) { types.push({ src, type: q[1].toLowerCase(), everywhere: /aren't on the battlefield/i.test(q[2]) }); continue; }
          q = /^(.+?) you control with power or toughness (\d+) or less can't be blocked\.?$/i.exec(line);
          if (q) { sneaky.push({ what: q[1], n: Number(q[2]) }); continue; }
          // Weathered Sentinels: "can attack players who attacked you during their last turn as though it didn't have defender".
          q = /^(.+?) can attack players who attacked you during their last turn as though it didn't have defender\.?$/i.exec(line);
          if (q) { if (isSelf(q[1], src) && other && other.attackedYou) fighting.push({ from: s, src, self: true, mine: true, attack: true, kw: '' }); continue; }
          // Banners: "Creatures you control of the chosen type get +1/+1" reads as "Elf creatures you control get +1/+1".
          if (/ of the chosen type\b/i.test(line)) {
            if (!src.chosenType) continue;
            line = line.replace(/ of the chosen type\b/i, '').replace(/^(other )?(\w+)/i, (all, o, w) => `${o || ''}${src.chosenType} ${w}`);
          }
          // Heraldic Banner: "Creatures you control of the chosen color get +1/+0." (color: a lord for that color only)
          let color = null;
          if (/ of the chosen color\b/i.test(line)) {
            if (!src.chosenColor) continue;
            color = src.chosenColor;
            line = line.replace(/ of the chosen color\b/i, '');
          }
          q = /^as long as there are (\w+) or more cards in your graveyard, (.+?) gets ([+-]\d+)\/([+-]\d+)(?: and (can't block|can't attack|has (.+?)))?\.?$/i.exec(line);
          if (q && isSelf(q[2], src)) {
            if (s.zones.graveyard.length >= toNumber(q[1])) threshold.push({ src, pow: Number(q[3]), tou: Number(q[4]), kws: q[6] ? grantKws(q[6]) : q[5] ? [q[5].toLowerCase()] : [] });
            continue;
          }
          let m = /^(other )?(.+?) you control can't be blocked except by two or more creatures\.?$/i.exec(line);
          if (m) { lords.push({ src, other: !!m[1], what: m[2], kws: ['menace'], pow: 0, tou: 0 }); continue; } // menace, older words
          // "Other creatures you control with defender get +0/+2" (Stalwart Shield-Bearers): withKw.
          // Door of Destinies: "Creatures you control of the chosen type get +1/+1 for each charge counter on this artifact."
          const per = /^(.+? you control) get ([+-])(\d+)\/([+-])(\d+) for each ([\w+/-]+) counter on (?:this \w+|it)\.?$/i.exec(line);
          if (per) {
            const k = (src.counters || {})[per[6].toLowerCase()] || 0;
            if (!k) continue;
            line = `${per[1]} get ${per[2]}${per[3] * k}/${per[4]}${per[5] * k}`;
          }
          m = /^(other )?(.+?) you control(?: with ([a-z]+(?: [a-z]+)?))? (?:get ([+-]\d+)\/([+-]\d+)(?: and have (.+?))?|have (.+?))\.?$/i.exec(line);
          if (m && m[2].includes(':')) continue; // an activated ability ("{2}: Elves you control get …"), not always on
          if (m) {
            const kws = grantKws(m[6] || m[7] || ''); // "protection from Dogs" is left to you; "protection from black and from red" isn't
            const pow = Number(m[4] || 0);
            const tou = Number(m[5] || 0);
            if (kws.length || pow || tou) lords.push({ src, other: !!m[1], what: m[2], withKw: (m[3] || '').toLowerCase(), kws, pow, tou, color });
            continue;
          }
          // Desmond Miles: "… for each other Assassin you control and each Assassin card in your graveyard."
          m = /^(.+?) gets ([+-]\d+)\/([+-]\d+) for each (other )?(.+?) you control(?: and each (.+?) cards? in your graveyard)?\.?$/i.exec(line);
          if (m && isSelf(m[1], src)) { each.push({ src, pow: Number(m[2]), tou: Number(m[3]), other: !!m[4], what: m[5], grave: m[6] || null }); continue; }
          // "Silverwing Squadron's power and toughness are each equal to the number of creatures you control."
          // Pestilence Rats: "… equal to the number of other Rats on the battlefield." (every table)
          m = /^(.+?)['’]s (power and toughness are each|power is|toughness is) equal to the number of (other )?(.+?) (you control|on the battlefield)\.?$/i.exec(line);
          if (m && isSelf(m[1], src)) each.push({ src, pow: /power/i.test(m[2]) ? 1 : 0, tou: /toughness/i.test(m[2]) ? 1 : 0, other: !!m[3], what: m[4], cda: true, everywhere: /battlefield/i.test(m[5]) });
          // Haughty Djinn, Consuming Aberration, Lord of Extinction: "… equal to the number of instant and sorcery cards in your graveyard"
          // ("cards in your opponents' graveyards", "cards in all graveyards").
          m = GRAVE_CDA.exec(line);
          if (m && isSelf(m[1], src)) {
            const where = m[4].toLowerCase();
            const from = where === 'your graveyard' ? [s] : where === 'all graveyards' ? tables : tables.filter(t => t !== s);
            const kinds = (m[3] || '').split(/\s+(?:and|or)\s+|,\s*/).map(k => k.trim()).filter(Boolean);
            const n = from.reduce((k, t) => k + t.zones.graveyard.filter(iid => !kinds.length || kinds.some(w => cardFits(t.cards[iid], singular(w)))).length, 0);
            each.push({ src, pow: /power/i.test(m[2]) ? 1 : 0, tou: /toughness/i.test(m[2]) ? 1 : 0, fixed: n, cda: true });
          }
        }
      }
      // Types first, since the rest checks them ("Assassins you control have menace").
      for (const c of Object.values(s.cards)) {
        const add = types.filter(t => t.src !== c && (c.zone === 'battlefield' ? G.isCreature(c) && !c.faceDown : t.everywhere && /\bcreature\b/i.test(front(c.typeLine))))
          .map(t => singular(t.type)).filter(t => !front(c.typeLine).toLowerCase().split(/[^a-z-]+/).includes(t));
        if (add.length) c.extraTypes = [...new Set(add)];
        else delete c.extraTypes;
      }
      const all = permanents(s);
      if (s.ringBearer && !all.some(c => c.iid === s.ringBearer && G.isCreature(c))) delete s.ringBearer; // it left: you'll choose another the next time
      // "commander creatures": its commander.
      const fitsWhat = (c, what) => {
        const w = what.replace(/^commander\s+/i, '');
        return (w === what || c.commander) && isA(c, w);
      };
      for (const c of creatures(s)) {
        const got = new Set();
        let pow = 0;
        let tou = 0;
        const lines = quoted.filter(q => !(q.other && q.src === c) && fitsWhat(c, q.what)).map(q => q.line);
        if (lines.length) c.grantedLines = lines;
        else delete c.grantedLines;
        // An aura on its equipment that says 'it has "Equipped creature has deathtouch."' (Rune of Mortality).
        G.attachmentsOf(s, c.iid).forEach(id => Object.values(s.cards[id].boosts || {}).forEach(b => (b.equipKw || []).forEach(k => got.add(k))));
        lords.forEach(l => {
          if ((l.other && l.src === c) || !isA(c, l.what) || (l.test && !l.test(c))) return;
          if (l.withKw && !stats(c, c.bot || defOf(c.id)).kw.has(l.withKw)) return;
          if (l.color && !stats(c, c.bot || defOf(c.id)).colors.includes(l.color)) return;
          l.kws.forEach(k => got.add(k));
          const per = l.perCounter ? (c.counters || {})[l.perCounter] || 0 : 1; // Toxrill: "for each slime counter on them"
          pow += l.pow * per;
          tou += l.tou * per;
        });
        fighting.forEach(f => {
          if ((f.mine && f.from !== s) || !(f.self ? f.src === c : isA(c, f.what))) return;
          if (f.yourTurn && (f.from.offTurn || (f.from === tables[0] && tables[0].offTurn))) return; // Baldin: its controller's turn only
          if (f.kw && !stats(c, c.bot || defOf(c.id)).kw.has(f.kw)) return;
          if (f.tough) got.add(TOUGH_DMG);
          if (f.attack) got.add(DEFENDER_ATTACKS);
        });
        const cda = { pow: 0, tou: 0 };
        threshold.filter(t => t.src === c).forEach(t => { pow += t.pow; tou += t.tou; t.kws.forEach(k => got.add(k)); });
        // Coat of Arms: +1/+1 for each other creature (any table) that shares a creature type with it.
        if (coats) {
          const subs = x => new Set((front(x.typeLine).split('—')[1] || '').toLowerCase().split(/\s+/).filter(Boolean).concat(x.extraTypes || []));
          const mineSubs = subs(c);
          const n = tables.flatMap(t => creatures(t)).filter(o => o !== c && [...subs(o)].some(w => mineSubs.has(w))).length;
          pow += coats * n;
          tou += coats * n;
        }
        byColors.forEach(b => {
          const k = colorsOfInst(c, defOf).length;
          if (b.src === c || (b.multi && k < 2)) return;
          pow += k;
          tou += k;
        });
        each.filter(e => e.src === c).forEach(e => {
          const n = e.fixed != null ? e.fixed : (e.everywhere ? tables.flatMap(t => permanents(t)) : all).filter(p => !(e.other && p === c) && isA(p, e.what)).length
            + (e.grave ? s.zones.graveyard.filter(iid => isA(s.cards[iid], e.grave)).length : 0);
          if (e.cda) { cda.pow += e.pow * n; cda.tou += e.tou * n; return; }
          pow += e.pow * n;
          tou += e.tou * n;
        });
        if (each.some(e => e.src === c && e.cda)) c.cda = cda;
        else delete c.cda;
        sneaky.forEach(t => { const st = stats(c, c.bot || defOf(c.id)); if (isA(c, t.what) && (st.pow <= t.n || st.tou <= t.n)) got.add('unblockable'); });
        // The FDC precons: conditional bonuses, base power and toughness, extra types, equipment that counts.
        let basePT = null;
        const moreTypes = [];
        for (const fx of extras) {
          const r = fx(c);
          if (!r) continue;
          pow += r.pow || 0;
          tou += r.tou || 0;
          (r.kws || []).forEach(k => got.add(k));
          moreTypes.push(...(r.types || []));
          if (r.basePT) basePT = r.basePT;
          if (r.lines) c.grantedLines = [...(c.grantedLines || []), ...r.lines];
        }
        for (const b of Object.values(c.boosts || {})) {
          if (!b) continue;
          if (b.perEach) { const k = permanents(s).filter(p => cardFits(p, b.perEach)).length; pow += k; tou += k; } // Nettlecyst
          if (b.perCommanderMv) { const k = Math.max(0, ...Object.values(s.cards).filter(p => p.commander).map(p => cmcOfInst(p, defOf))); pow += k; tou += k; } // Tangleweave Armor
          moreTypes.push(...(b.types || [])); // Angelic Destiny: "is an Angel in addition to its other types"
        }
        if (c.imprint) { basePT = c.imprint.pt; moreTypes.push(...c.imprint.types); } // Duplicant
        // The Ring-bearer (ringTempts): legendary, not blocked by bigger creatures, and more with each time the Ring tempted you.
        if (s.ringBearer === c.iid) c.isRingBearer = true; // stats' ringBearer (Lord of the Nazgûl's protection)
        else delete c.isRingBearer;
        if (s.ringBearer === c.iid) {
          moreTypes.push('legendary');
          got.add('evade greater power');
          const lines = RING_LINES.slice(0, Math.max(0, (s.ringTempts || 1) - 1));
          if (lines.length) c.grantedLines = [...(c.grantedLines || []), ...lines];
        }
        if (c.basePTUntil) basePT = c.basePTUntil; // Lord of the Nazgûl: "… have base power and toughness 9/9 until end of turn"
        if (basePT) c.basePT = basePT;
        else delete c.basePT;
        if (moreTypes.length) c.extraTypes = [...new Set([...(c.extraTypes || []), ...moreTypes.map(t => t.toLowerCase())])];
        // Rishkar: 'Each creature you control with a counter on it has "{T}: Add {G}."' (game.js's sourceOf)
        if (s.counterMana && Object.values(c.counters || {}).some(n => n > 0)) c.grantedMana = s.counterMana;
        else if (stewardMana(s, defOf)) c.grantedMana = stewardMana(s, defOf); // Steward of the Harvest
        else delete c.grantedMana;
        if (got.size) c.granted = [...got];
        else delete c.granted;
        if (pow || tou) c.anthem = { pow, tou };
        else delete c.anthem;
      }
      // How many creatures have defender (Overgrown Battlement's and Axebane Guardian's mana, game.js).
      s.kwCount = { defender: creatures(s).filter(c => stats(c, c.bot || defOf(c.id)).kw.has('defender')).length };
    }
  }
  // Always-on lines of the FDC precons, read for grantsOnce. Returns (c) → { pow, tou, kws, types,
  // basePT, lines } for each creature c on table s (null when it doesn't apply to c), or null for a
  // line it doesn't read. Some set table-wide rules instead (s.extraC, s.keepRed, s.counterMana).
  const MUST_ATTACK = 'attacks each combat if able';
  const NO_COMBAT_DMG = 'prevent combat damage to it';
  const CAP_UNTAP = /^whenever a creature you control becomes tapped during your turn, if it's the first time that creature has become tapped this turn, untap it\.?$/i;
  const SOULBOND = /^as long as this creature is paired with another creature, each of those creatures gets \+(\d+)\/\+(\d+)\.?$/i;
  const LONE_WOLF = /^you may have this creature assign its combat damage as though it weren't blocked\.?$/i;
